-- ---------------------------------------------------------------------------
-- DeadlineBuddy - demo data
--
--   mysql -u root -p < db/seed.sql
--
-- Safe to re-run: it clears the three tables first and restarts the ids, so
-- running it twice gives the same database rather than duplicate rows.
--
-- Two accounts. Both passwords are stored as PBKDF2-HMAC-SHA256 hashes
-- generated by com.util.Passwords - the same code the application verifies
-- with. No plaintext password is stored anywhere.
--
--   ananya.pawar@student.edu  /  123456789    (the demo account, full data)
--   rohan.mehta@student.edu   /  rohan1234    (a second student, to show that
--                                              one student cannot see the
--                                              other's subjects or tasks)
--
-- Due dates are written relative to CURDATE(), so a fresh install always has
-- something overdue, something due today and something coming up, whenever it
-- is installed. completed_at is filled in for exactly the completed tasks, and
-- left NULL otherwise - the same invariant the application maintains and the
-- ck_tasks_completed_at constraint enforces.
-- ---------------------------------------------------------------------------

USE deadlinebuddy_db;

DELETE FROM tasks;
DELETE FROM subjects;
DELETE FROM users;
ALTER TABLE tasks     AUTO_INCREMENT = 1;
ALTER TABLE subjects  AUTO_INCREMENT = 1;
ALTER TABLE users     AUTO_INCREMENT = 1;

