-- ---------------------------------------------------------------------------
-- What the dashboard should show for Ananya straight after seeding:
--
--   total 16, completed 6, in progress 2, pending 8, overdue 2, due today 2,
--   completion 38%
--
-- and for Rohan: total 4, completed 1, in progress 1, pending 2, overdue 0,
-- due today 0, completion 25%.
-- ---------------------------------------------------------------------------
SELECT u.email,
       COUNT(t.id)                                                        AS total,
       SUM(t.status = 'COMPLETED')                                        AS completed,
       SUM(t.status = 'IN_PROGRESS')                                      AS in_progress,
       SUM(t.status = 'PENDING')                                          AS pending,
       SUM(t.status <> 'COMPLETED' AND t.due_date <  CURDATE())           AS overdue,
       SUM(t.status <> 'COMPLETED' AND t.due_date =  CURDATE())           AS due_today,
       ROUND(SUM(t.status = 'COMPLETED') / COUNT(t.id) * 100)             AS pct
FROM users u LEFT JOIN tasks t ON t.user_id = u.id
GROUP BY u.id, u.email;
